def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 140:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        return min(budget, 18.0)

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight = slots <= 1
    danger = hp <= 2 or no_water >= 1
    severe_danger = hp <= 1 or no_water >= 2
    ample_supply = supply >= 24

    if severe_danger:
        bid = max(72.0, highest_prev + 3.0)
        return float(min(budget, bid))

    if danger:
        if tight:
            bid = max(68.0, highest_prev + 2.0)
        else:
            bid = max(56.0, avg_prev * 0.6 + 6.0)
        return float(min(budget, bid))

    if tight:
        if highest_prev >= 150:
            bid = 18.0
        elif highest_prev >= 120:
            bid = 26.0
        else:
            bid = max(38.0, highest_prev * 0.55 + 2.0)
    else:
        if ample_supply and rich_opp >= 2 and highest_prev >= 120:
            bid = 12.0
        elif highest_prev >= 140:
            bid = 14.0
        elif highest_prev >= 100:
            bid = 22.0
        else:
            bid = max(20.0, avg_prev * 0.35 + 4.0)

    if urgent_opp >= 2 and not danger:
        bid *= 0.9

    if day >= 8 and hp >= 4:
        bid *= 0.9

    if budget < 60:
        bid = min(bid, budget * 0.7)

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    supply = int(day_context['supply'])  # ensure integer

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Gather yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            yesterday_bids.append(prev['bid'])

    high_prev = max(yesterday_bids) if yesterday_bids else 0.0

    # Urgency due to no_water_days
    if hp <= 2 or no_water_days > 0:
        # Need water urgently, bid aggressively but within budget
        target_bid = min(budget, DAILY_SALARY * 1.2)
        if high_prev > 0:
            # Outbid highest by a small margin, but cap
            target_bid = max(target_bid, high_prev + 2.0)
        return min(budget, target_bid)

    # If supply is plentiful, we can afford to bid low
    if supply >= 2 * WATER_REQ:
        # Only bid enough to possibly win if others bid low
        if high_prev > 0 and high_prev < DAILY_SALARY * 0.6:
            # Compete modestly
            bid = min(budget, high_prev + 1.5)
        else:
            bid = min(budget, DAILY_SALARY * 0.3)
        return max(0, min(budget, bid))

    # Supply is scarce
    if high_prev >= DAILY_SALARY * 0.85:
        # Opponent aggressive, conserve unless we have high HP
        if hp > 4:
            return min(budget, DAILY_SALARY * 0.4)
        else:
            # Must try to win
            return min(budget, DAILY_SALARY * 0.95)
    else:
        # Moderate competition, bid just above highest
        return min(budget, max(DAILY_SALARY * 0.5, high_prev + 1.5))
